<?php require __DIR__.'/bootstrap.php';require __DIR__.'/webauthn.php';$u=require_login();try{$v=webauthn_json();$challenge=$_SESSION['webauthn_register_challenge']??'';unset($_SESSION['webauthn_register_challenge']);$clientRaw=b64u_decode($v['response']['clientDataJSON']??'');$attRaw=b64u_decode($v['response']['attestationObject']??'');if($clientRaw===false||$attRaw===false)throw new RuntimeException('Resposta inválida');$client=json_decode($clientRaw,true);if(!is_array($client))throw new RuntimeException('ClientData inválido');webauthn_client_data($client,'webauthn.create',$challenge);$i=0;$att=cbor_read($attRaw,$i);$authData=$att['authData']??'';if(!is_string($authData)||strlen($authData)<55)throw new RuntimeException('Credencial inválida');$a=webauthn_auth_data($authData);if(($a['flags']&0x05)!==0x05||hash('sha256',webauthn_rp_id(),true)!==substr($authData,0,32))throw new RuntimeException('Biometria não confirmada');$pos=37+16;$len=unpack('n',substr($authData,$pos,2))[1];$pos+=2;$credentialId=substr($authData,$pos,$len);$pos+=$len;$ci=0;$cose=cbor_read(substr($authData,$pos),$ci);$x=$cose['-2']??null;$y=$cose['-3']??null;if(!is_string($x)||!is_string($y)||strlen($x)!==32||strlen($y)!==32)throw new RuntimeException('Chave biométrica incompatível');$check=$pdo->prepare('SELECT id FROM webauthn_credentials WHERE credential_id=?');$check->execute([$credentialId]);if($check->fetch())throw new RuntimeException('Esta biometria já está cadastrada.');$pdo->prepare('INSERT INTO webauthn_credentials(user_id,credential_id,public_key_x,public_key_y,sign_count) VALUES(?,?,?,?,?)')->execute([$u['id'],$credentialId,$x,$y,$a['count']]);json_out(['ok'=>true,'message'=>'Biometria cadastrada neste dispositivo.']);}catch(Throwable $e){json_out(['error'=>$e->getMessage()],422);}
